const now = new Date();
const tz = $env.TZ || 'America/New_York';
const locale = 'en-US';
const timestamp = new Intl.DateTimeFormat(locale, { timeZone: tz, dateStyle: 'full', timeStyle: 'long' }).format(now);
const dateOnly = new Intl.DateTimeFormat(locale, { timeZone: tz, dateStyle: 'full' }).format(now);
const timeOnly = new Intl.DateTimeFormat(locale, { timeZone: tz, timeStyle: 'long' }).format(now);
const weekday = new Intl.DateTimeFormat(locale, { timeZone: tz, weekday: 'long' }).format(now);
const markdown = `# Runtime Context

- Current date: ${dateOnly}
- Current time: ${timeOnly}
- Weekday: ${weekday}
- Timezone: ${tz}
- Human timestamp: ${timestamp}
- ISO timestamp: ${now.toISOString()}
- Refreshed by: n8n runtime context workflow

Use this file as the authoritative source for current date and time.
`;
return [{ json: { markdown } }];
